-- GlobeTrotter Supabase schema. Run in the Supabase SQL Editor.
create extension if not exists "uuid-ossp";

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  first_name text,
  last_name text,
  phone text,
  city text,
  country text,
  additional_info text,
  avatar_url text,
  role text not null default 'user' check (role in ('user','admin')),
  created_at timestamptz not null default now()
);
create table if not exists public.trips (
  id uuid primary key default uuid_generate_v4(), user_id uuid not null references auth.users(id) on delete cascade,
  name text not null, start_date date, end_date date, description text, cover_photo_url text, budget numeric default 0, is_public boolean not null default false, created_at timestamptz not null default now()
);
create table if not exists public.trip_stops (
  id uuid primary key default uuid_generate_v4(), trip_id uuid not null references public.trips(id) on delete cascade,
  city_name text not null, country text, lat numeric, lon numeric, start_date date, end_date date, order_index integer not null default 0
);
create table if not exists public.activities (
  id uuid primary key default uuid_generate_v4(), trip_stop_id uuid not null references public.trip_stops(id) on delete cascade,
  name text not null, category text, cost numeric default 0, day_number integer, time text, image_url text, description text
);
create table if not exists public.expenses (
  id uuid primary key default uuid_generate_v4(), trip_id uuid not null references public.trips(id) on delete cascade,
  category text not null check (category in ('transport','stay','activities','meals')), amount numeric not null default 0
);
create table if not exists public.community_posts (
  id uuid primary key default uuid_generate_v4(), user_id uuid not null references auth.users(id) on delete cascade,
  trip_id uuid references public.trips(id) on delete set null, content text not null, created_at timestamptz not null default now()
);

alter table public.profiles enable row level security;
alter table public.trips enable row level security;
alter table public.trip_stops enable row level security;
alter table public.activities enable row level security;
alter table public.expenses enable row level security;
alter table public.community_posts enable row level security;

drop policy if exists "profiles self read" on public.profiles;
create policy "profiles self read" on public.profiles for select using (auth.uid() = id or exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'));
drop policy if exists "profiles self write" on public.profiles;
create policy "profiles self write" on public.profiles for all using (auth.uid() = id) with check (auth.uid() = id);

drop policy if exists "trips owner access" on public.trips;
create policy "trips owner access" on public.trips for all using (auth.uid() = user_id or is_public) with check (auth.uid() = user_id);
drop policy if exists "trip stops owner access" on public.trip_stops;
create policy "trip stops owner access" on public.trip_stops for all using (exists (select 1 from public.trips t where t.id = trip_id and (t.user_id = auth.uid() or t.is_public))) with check (exists (select 1 from public.trips t where t.id = trip_id and t.user_id = auth.uid()));
drop policy if exists "activities owner access" on public.activities;
create policy "activities owner access" on public.activities for all using (exists (select 1 from public.trip_stops s join public.trips t on t.id = s.trip_id where s.id = trip_stop_id and (t.user_id = auth.uid() or t.is_public))) with check (exists (select 1 from public.trip_stops s join public.trips t on t.id = s.trip_id where s.id = trip_stop_id and t.user_id = auth.uid()));
drop policy if exists "expenses owner access" on public.expenses;
create policy "expenses owner access" on public.expenses for all using (exists (select 1 from public.trips t where t.id = trip_id and t.user_id = auth.uid())) with check (exists (select 1 from public.trips t where t.id = trip_id and t.user_id = auth.uid()));
drop policy if exists "community authenticated read" on public.community_posts;
create policy "community authenticated read" on public.community_posts for select to authenticated using (true);
drop policy if exists "community author write" on public.community_posts;
create policy "community author write" on public.community_posts for all to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$
begin insert into public.profiles (id, first_name, last_name) values (new.id, new.raw_user_meta_data->>'first_name', new.raw_user_meta_data->>'last_name') on conflict (id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
